var frame = Solution.EncodeFrame("hello");
Cj.Eq(frame.Length, 4 + 5, "prefix + payload");
Cj.Eq(frame[0], 5, "LE length low byte");
Cj.Eq(Solution.DecodeFrame(frame), "hello", "decodes exactly");

var frame = Solution.EncodeFrame("truncate me please");
var bad = frame[..^3];   // cut the last 3 payload bytes
var ex = await Cj.ThrowsAsync<ArgumentException>(() => Task.Run(() => Solution.DecodeFrame(bad)));
Cj.True(ex is not null, "truncated frame must throw, not decode garbage");
